pub fn hash_reader(mut reader: impl Read, chunk_bytes: usize) -> Result<(u64, String), OwnedError> {
    let mut buffer = vec![0_u8; chunk_bytes.max(1)];
    let mut hasher = Sha256::new();
    let mut total = 0_u64;
