1	//! Streaming SHA-256 over in-memory bytes and confined files.
2	//!
3	//! This is a native primitive because SHA-256 is 64 rounds of 32-bit modular
4	//! addition, rotation, and exclusive-or per 64-byte block. A gigabyte input is
5	//! roughly 16 million blocks, and MLPL has no native 32-bit integer type to
6	//! express the rounds in, so the algorithm is not merely slow in the
7	//! interpreter but impractical. Nothing here is application-specific.
8	
9	use std::collections::{BTreeMap, BTreeSet};
10	use std::fmt::Write as _;
11	use std::fs::File;
12	use std::io::Read;
13	use std::path::{Component, Path, PathBuf};
14	
15	use mlpl_extension_sdk::{OwnedError, Value};
16	use sha2::{Digest, Sha256};
17	
18	/// Largest single read buffer (16 MiB).
19	const MAX_CHUNK_BYTES: i64 = 16 * 1024 * 1024;
20	/// Default read buffer when a caller does not choose one (1 MiB).
21	pub const DEFAULT_CHUNK_BYTES: usize = 1024 * 1024;
22	
23	/// Hashes one in-memory byte string.
24	///
25	/// # Errors
26	///
27	/// Returns an invalid-argument error unless called with exactly one bytes
28	/// value.
29	pub fn sha256_bytes_value(arguments: &[Value]) -> Result<Value, OwnedError> {
30	    let bytes = match arguments {
31	        [Value::Bytes(bytes)] => bytes,
32	        [_] => return Err(invalid("sha256_bytes argument must be bytes")),
33	        _ => return Err(invalid("sha256_bytes expects exactly one argument")),
34	    };
35	    let (_, digest) = hash_reader(bytes.as_slice(), DEFAULT_CHUNK_BYTES)?;
36	    Ok(Value::String(digest))
37	}
38	
39	/// Hashes an existing file beneath an explicit root, streaming it in bounded
40	/// chunks so the whole artifact is never resident.
41	///
42	/// # Errors
43	///
44	/// Returns an invalid-argument error for a malformed record, a non-canonical
45	/// root, or an unconfined path, and an extension error when the file cannot be
46	/// opened or read.
47	pub fn sha256_file_value(arguments: &[Value]) -> Result<Value, OwnedError> {
48	    let request = FileRequest::parse(arguments)?;
49	    let path = request.confine()?;
50	    let file = File::open(&path)
51	        .map_err(|error| OwnedError::extension(format!("cannot open file: {error}")))?;
52	    let metadata = file
53	        .metadata()
54	        .map_err(|error| OwnedError::extension(format!("cannot read file metadata: {error}")))?;
55	    if !metadata.is_file() {
56	        return Err(invalid("path does not name a regular file"));
57	    }
58	    let (bytes, digest) = hash_reader(file, request.chunk_bytes)?;
59	    Ok(Value::Record(
60	        [
61	            ("sha256".to_owned(), Value::String(digest)),
62	            (
63	                "bytes".to_owned(),
64	                Value::I64(i64::try_from(bytes).unwrap_or(i64::MAX)),
65	            ),
66	        ]
67	        .into_iter()
68	        .collect(),
69	    ))
70	}
71	
72	struct FileRequest {
73	    root: PathBuf,
74	    relative_path: PathBuf,
75	    chunk_bytes: usize,
76	}
77	
78	impl FileRequest {
79	    fn parse(arguments: &[Value]) -> Result<Self, OwnedError> {
80	        let fields = match arguments {
81	            [Value::Record(fields)] => fields,
82	            [_] => return Err(invalid("sha256_file argument must be a record")),
83	            _ => return Err(invalid("sha256_file expects exactly one argument")),
84	        };
85	        let expected = BTreeSet::from(["chunk_bytes", "path", "root"]);
86	        let actual = fields.keys().map(String::as_str).collect::<BTreeSet<_>>();
87	        if actual != expected {
88	            return Err(invalid("sha256_file fields do not match the V1 contract"));
89	        }
90	        let root = PathBuf::from(string_field(fields, "root")?);
91	        if !root.is_absolute() {
92	            return Err(invalid("root must be an absolute directory"));
93	        }
94	        let relative_path = confined_relative_path(string_field(fields, "path")?)?.to_path_buf();
95	        let chunk_bytes = match fields.get("chunk_bytes") {
96	            Some(Value::I64(value)) if (1..=MAX_CHUNK_BYTES).contains(value) => *value,
97	            Some(Value::I64(_)) => {
98	                return Err(invalid(format!(
99	                    "chunk_bytes must be between 1 and {MAX_CHUNK_BYTES}"
100	                )));
101	            }
102	            Some(_) => return Err(invalid("chunk_bytes must be i64")),
103	            None => return Err(invalid("missing field: chunk_bytes")),
104	        };
105	        Ok(Self {
106	            root,
107	            relative_path,
108	            chunk_bytes: usize::try_from(chunk_bytes)
109	                .map_err(|_| invalid("chunk_bytes is invalid"))?,
110	        })
111	    }
112	
113	    fn confine(&self) -> Result<PathBuf, OwnedError> {
114	        let root = self
115	            .root
116	            .canonicalize()
117	            .map_err(|_| invalid("root must be an existing directory"))?;
118	        if !root.is_dir() {
119	            return Err(invalid("root must be an existing directory"));
120	        }
121	        let target = root.join(&self.relative_path);
122	        let canonical = target
123	            .canonicalize()
124	            .map_err(|_| invalid("path must name an existing file beneath the root"))?;
125	        if !canonical.starts_with(&root) {
126	            return Err(invalid("path escapes the configured root"));
127	        }
128	        Ok(canonical)
129	    }
130	}
131	
132	/// Streams `reader` in bounded chunks, returning the byte count and the
133	/// lowercase hexadecimal digest. Shared by the bytes and file surfaces so one
134	/// implementation defines the result.
135	pub fn hash_reader(mut reader: impl Read, chunk_bytes: usize) -> Result<(u64, String), OwnedError> {
136	    let mut buffer = vec![0_u8; chunk_bytes.max(1)];
137	    let mut hasher = Sha256::new();
138	    let mut total = 0_u64;
139	    loop {
140	        let size = match reader.read(&mut buffer) {
141	            Ok(0) => break,
142	            Ok(size) => size,
143	            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
144	            Err(error) => {
145	                return Err(OwnedError::extension(format!("read failed: {error}")));
146	            }
147	        };
148	        total = total.saturating_add(u64::try_from(size).unwrap_or(u64::MAX));
149	        hasher.update(&buffer[..size]);
150	    }
151	    Ok((total, hex(&hasher.finalize())))
152	}
153	
154	/// Renders a digest as lowercase hexadecimal.
155	pub fn hex(digest: &[u8]) -> String {
156	    let mut text = String::with_capacity(digest.len() * 2);
157	    for byte in digest {
158	        let _ = write!(text, "{byte:02x}");
159	    }
160	    text
161	}
162	
163	fn confined_relative_path(value: &str) -> Result<&Path, OwnedError> {
164	    let path = Path::new(value);
165	    if value.is_empty()
166	        || path.is_absolute()
167	        || !path
168	            .components()
169	            .all(|component| matches!(component, Component::Normal(_)))
170	    {
171	        return Err(invalid("path must be a confined relative path"));
172	    }
173	    Ok(path)
174	}
175	
176	fn string_field<'a>(
177	    fields: &'a BTreeMap<String, Value>,
178	    name: &str,
179	) -> Result<&'a str, OwnedError> {
180	    match fields.get(name) {
181	        Some(Value::String(value)) => Ok(value),
182	        Some(_) => Err(invalid(format!("{name} must be a string"))),
183	        None => Err(invalid(format!("missing field: {name}"))),
184	    }
185	}
186	
187	fn invalid(message: impl Into<String>) -> OwnedError {
188	    OwnedError::invalid_argument(message)
189	}

