1	//! Filesystem and network effects for bounded large-artifact downloads:
2	//! confinement under an explicit root, verified reuse, streamed hashing into
3	//! a temporary file, and atomic publication.
4	
5	use std::fs::{self, File};
6	use std::io::{Read, Write};
7	use std::path::{Path, PathBuf};
8	
9	use mlpl_extension_digest::hex;
10	use mlpl_extension_sdk::{OwnedError, Value};
11	use sha2::{Digest, Sha256};
12	use tempfile::{Builder, NamedTempFile};
13	
14	use crate::download_plan::{DOWNLOAD_MAX_REDIRECTS, DownloadPlan};
15	use crate::fields::{invalid, record};
16	
17	/// Downloads one artifact of declared length and SHA-256 digest into a
18	/// confined path beneath `root`, streaming bounded chunks through a temporary
19	/// file and renaming it into place only after verification.
20	///
21	/// An existing target is reused, without network access, when its size and
22	/// digest already verify; otherwise it is replaced by the verified transfer.
23	/// Every failure removes the temporary file and leaves no partial output.
24	///
25	/// # Errors
26	///
27	/// Returns an invalid-argument error for malformed or unconfined requests and
28	/// an extension error for status, transport, length, digest, or filesystem
29	/// failures.
30	pub fn download_value(arguments: &[Value]) -> Result<Value, OwnedError> {
31	    let plan = DownloadPlan::parse(arguments)?;
32	    let target = confine(&plan)?;
33	    if let Some(sha256) = verified_existing(&plan, &target)? {
34	        return Ok(outcome(&plan, &target, sha256, true));
35	    }
36	    let sha256 = fetch_into(&plan, &target)?;
37	    Ok(outcome(&plan, &target, sha256, false))
38	}
39	
40	fn confine(plan: &DownloadPlan) -> Result<PathBuf, OwnedError> {
41	    let root = plan
42	        .root
43	        .canonicalize()
44	        .map_err(|_| invalid("root must be an existing directory"))?;
45	    if !root.is_dir() {
46	        return Err(invalid("root must be an existing directory"));
47	    }
48	    let target = root.join(&plan.relative_path);
49	    let parent = target
50	        .parent()
51	        .ok_or_else(|| invalid("path has no parent directory"))?;
52	    fs::create_dir_all(parent).map_err(|error| {
53	        OwnedError::extension(format!("cannot create parent directory: {error}"))
54	    })?;
55	    let canonical_parent = parent
56	        .canonicalize()
57	        .map_err(|_| invalid("path parent cannot be resolved"))?;
58	    if !canonical_parent.starts_with(&root) {
59	        return Err(invalid("path escapes the configured root"));
60	    }
61	    if target.exists() {
62	        let canonical = target
63	            .canonicalize()
64	            .map_err(|_| invalid("path cannot be resolved"))?;
65	        if !canonical.starts_with(&root) {
66	            return Err(invalid("path escapes the configured root"));
67	        }
68	        if canonical.is_dir() {
69	            return Err(invalid("path names an existing directory"));
70	        }
71	    }
72	    Ok(target)
73	}
74	
75	fn verified_existing(plan: &DownloadPlan, target: &Path) -> Result<Option<String>, OwnedError> {
76	    let Ok(metadata) = fs::metadata(target) else {
77	        return Ok(None);
78	    };
79	    if !metadata.is_file() || metadata.len() != plan.expected_bytes {
80	        return Ok(None);
81	    }
82	    let file = File::open(target)
83	        .map_err(|error| OwnedError::extension(format!("cannot read existing file: {error}")))?;
84	    let (bytes, sha256) = hash_reader(file, plan.chunk_bytes, plan.expected_bytes, |_| Ok(()))?;
85	    if bytes == plan.expected_bytes && sha256 == plan.sha256 {
86	        Ok(Some(sha256))
87	    } else {
88	        Ok(None)
89	    }
90	}
91	
92	fn fetch_into(plan: &DownloadPlan, target: &Path) -> Result<String, OwnedError> {
93	    let agent = ureq::AgentBuilder::new()
94	        .timeout(plan.timeout)
95	        .redirects(DOWNLOAD_MAX_REDIRECTS)
96	        .build();
97	    let response = match agent.get(&plan.url).call() {
98	        Ok(response) => response,
99	        Err(ureq::Error::Status(status, _)) => {
100	            return Err(OwnedError::extension(format!(
101	                "HTTP status {status} is not a successful download"
102	            )));
103	        }
104	        Err(ureq::Error::Transport(error)) => {
105	            return Err(OwnedError::extension(format!(
106	                "HTTP transport failure: {}",
107	                error.kind()
108	            )));
109	        }
110	    };
111	    // A redirect past the budget is returned as a successful call, so the
112	    // status is checked here rather than trusting the transport's result.
113	    if !(200..300).contains(&response.status()) {
114	        return Err(OwnedError::extension(format!(
115	            "HTTP status {} is not a successful download",
116	            response.status()
117	        )));
118	    }
119	    plan.check_declared_length(response.header("content-length"))?;
120	    let mut temporary = temporary_file(target)?;
121	    let (bytes, sha256) = hash_reader(
122	        response.into_reader(),
123	        plan.chunk_bytes,
124	        plan.expected_bytes,
125	        |chunk| {
126	            temporary.write_all(chunk).map_err(|error| {
127	                OwnedError::extension(format!("cannot write temporary file: {error}"))
128	            })
129	        },
130	    )?;
131	    plan.verify_transfer(bytes, &sha256)?;
132	    temporary
133	        .as_file()
134	        .sync_all()
135	        .map_err(|error| OwnedError::extension(format!("cannot flush temporary file: {error}")))?;
136	    temporary.persist(target).map_err(|error| {
137	        OwnedError::extension(format!("cannot publish download: {}", error.error))
138	    })?;
139	    Ok(sha256)
140	}
141	
142	fn temporary_file(target: &Path) -> Result<NamedTempFile, OwnedError> {
143	    let parent = target
144	        .parent()
145	        .ok_or_else(|| invalid("path has no parent directory"))?;
146	    let name = target
147	        .file_name()
148	        .and_then(|name| name.to_str())
149	        .ok_or_else(|| invalid("path has no file name"))?;
150	    Builder::new()
151	        .prefix(&format!(".{name}.part-"))
152	        .tempfile_in(parent)
153	        .map_err(|error| OwnedError::extension(format!("cannot create temporary file: {error}")))
154	}
155	
156	/// Streams `reader` in bounded chunks through `sink` while hashing, stopping
157	/// as soon as more than `limit` bytes arrive. A read failure before `limit`
158	/// bytes is reported as a truncated transfer so callers see one vocabulary.
159	fn hash_reader(
160	    mut reader: impl Read,
161	    chunk_bytes: usize,
162	    limit: u64,
163	    mut sink: impl FnMut(&[u8]) -> Result<(), OwnedError>,
164	) -> Result<(u64, String), OwnedError> {
165	    let mut buffer = vec![0_u8; chunk_bytes];
166	    let mut hasher = Sha256::new();
167	    let mut total = 0_u64;
168	    loop {
169	        let size = match reader.read(&mut buffer) {
170	            Ok(0) => break,
171	            Ok(size) => size,
172	            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
173	            Err(error) => {
174	                return Err(OwnedError::extension(format!(
175	                    "transfer truncated after {total} of {limit} bytes: {error}"
176	                )));
177	            }
178	        };
179	        total = total.saturating_add(u64::try_from(size).unwrap_or(u64::MAX));
180	        if total > limit {
181	            return Err(OwnedError::extension(format!(
182	                "transfer exceeds expected_bytes {limit}"
183	            )));
184	        }
185	        hasher.update(&buffer[..size]);
186	        sink(&buffer[..size])?;
187	    }
188	    Ok((total, hex(&hasher.finalize())))
189	}
190	
191	fn outcome(plan: &DownloadPlan, target: &Path, sha256: String, reused: bool) -> Value {
192	    record([
193	        ("path", Value::String(target.to_string_lossy().into_owned())),
194	        (
195	            "bytes",
196	            Value::I64(i64::try_from(plan.expected_bytes).unwrap_or(i64::MAX)),
197	        ),
198	        ("sha256", Value::String(sha256)),
199	        ("reused", Value::Bool(reused)),
200	    ])
201	}

